    // Only application copy goes through this catalogue. Ledger identifiers and user names stay stable.
    internal static class UiText
    {
        private static string language = "en";
        internal static CultureInfo Culture { get; private set; }
        internal static StringComparer Comparer { get; private set; }
        static UiText() { Language = "en"; }
        internal static string Language
        {
            get { return language; }
            set
            {
                language = value;
                Culture = CultureInfo.GetCultureInfo(value == "el" ? "el-GR" : value == "cs" ? "cs-CZ" : "en-GB");
                Comparer = StringComparer.Create(Culture, true);
            }
        }
        internal static string Get(string english)
        {
            if (Language == "en" || english == null) return english;
            string[] values;
            return Translations.TryGetValue(english, out values) ? values[Language == "el" ? 0 : 1] : english;
        }
        internal static string Format(string english, params object[] args)
        { return String.Format(Culture, Get(english), args); }

